// sentences with numbers or names inside
const TN_PAT=[
  [/^(\d+) HIT COMBO$/,m=>m[1]+' DARBAT'],[/^(\d+) HIT JUGGLE$/,m=>m[1]+' DARBAT FIL HWA'],
  [/^CHAPTER (\d+)$/,m=>'FASL '+m[1]],
  [/^ROUND (\d+)$/,m=>'ROUND '+m[1]],[/^STAGE (\d+) OF (\d+)$/,m=>'MAR7LA '+m[1]+' MEN '+m[2]],
  [/^Dummy: (.+)$/,m=>'Dummy: '+T(m[1])],[/^Meter: (.+)$/,m=>'Jauge: '+(m[1]==='Normal'?'3adia':T(m[1]))],
  [/^Sound: (.+)$/,m=>'Sout: '+T(m[1])],[/^Vibration: (.+)$/,m=>'Rja7a: '+T(m[1])],[/^Button size: (.+)$/,m=>'9ad el boutonet: '+T(m[1])],
  [/^D-pad on the (.+)$/,m=>'El D-pad 3al '+T(m[1])],
  [/^Your friend picked (.+)\.$/,m=>'Sa7bek 5tar '+m[1]+'.'],
  [/^Special: (.+)$/,m=>'Special: '+T(m[1])],[/^SUPER: (.+)$/,m=>'SUPER: '+T(m[1])],
  [/^LAST BREATH: (.+?)\. (.+)$/,m=>'A5ER NAFES: '+T(m[1])+'. '+T(m[2])],
  [/^DUMMY: (.+) · LAST COMBO:$/,m=>'DUMMY: '+T(m[1].charAt(0)+m[1].slice(1).toLowerCase()).toUpperCase()+' · A5ER COMBO:'],
  [/^(.+) · (.+)$/,m=>T(m[1])+' · '+T(m[2])],
  [/^Stage (\d+) of (\d+) cleared\. Next up:$/,m=>'Kammalt el mar7la '+m[1]+' men '+m[2]+'. Elli ba3dou:'],
  [/^from (.+), at (.+)\.$/,m=>'men '+T(m[1])+', fi '+T(m[2])+'.'],
  [/^(.+) stops you at stage (\d+) of (\d+)\. Continue\?$/,m=>m[1]+' w9fek fil mar7la '+m[2]+' men '+m[3]+'. Tkammel?'],
  [/^(.+) takes it (\d+)–(\d+)\. Yezzi, go again\.$/,m=>m[1]+' rbe7 '+m[2]+'–'+m[3]+'. Yezzi, 3awed.'],
  [/^HITS,$/,()=>'DARBAT,'],[/^DMG$/,()=>'DARR'],
  [/^ONLINE (\d+)MS$/,m=>'ONLINE '+m[1]+'MS'],
];
let LANG='tn';
function T(s){
  if(LANG!=='tn'||typeof s!=='string')return s;
  const m=s.match(/^(\s*)([\s\S]*?)(\s*)$/),core=m[2];if(!core)return s;
  let r=TN[core];
  if(r===undefined&&core.endsWith('!')&&TN[core.slice(0,-1)]!==undefined)r=TN[core.slice(0,-1)]+'!';
  if(r===undefined)for(const[re,f] of TN_PAT){const mm=core.match(re);if(mm){r=f(mm);break}}
  return r===undefined?s:m[1]+r+m[3];
}
